1	=============== core/RV32core.v
2	     1	`timescale 1ns / 1ps
3	     2	
4	     3	module  RV32core(
5	     4	        input debug_en,  // debug enable
6	     5	        input debug_step,  // debug step clock
7	     6	        input [6:0] debug_addr,  // debug address
8	     7	        output[31:0] debug_data,  // debug data
9	     8	        output[31:0] wb_addr,
10	     9	        output[31:0] wb_data,
11	    10	        output reg [31:0] clk_counter,
12	    11	        input clk,  // main clock
13	    12	        input rst,  // synchronous reset
14	    13	        input interrupter  // interrupt source, for future use
15	    14	    );
16	    15	
17	    16	    wire debug_clk;
18	    17	    wire[31:0] debug_regs;
19	    18	    reg[31:0] Test_signal;
20	    19		assign debug_data = debug_addr[5] ? Test_signal : debug_regs;
21	    20	
22	    21	    debug_clk clock(.clk(clk),.debug_en(debug_en),.debug_step(debug_step),.debug_clk(debug_clk));
23	    22	
24	    23	    wire PC_EN_IF, IS_EN, FU_ALU_EN, FU_mem_EN, FU_mul_EN, FU_div_EN, FU_jump_EN;
25	    24	    wire RegWrite_ctrl, ALUSrcA_ctrl, ALUSrcB_ctrl, mem_w_ctrl;
26	    25	    wire[2:0] ImmSel_ctrl, bhw_ctrl, DatatoReg_ctrl;
27	    26	    wire[3:0] ALUControl_ctrl;
28	    27	    wire[4:0] Jump_ctrl;
29	    28	    wire[4:0] rs1_addr_ctrl, rs2_addr_ctrl, rd_ctrl;
30	    29	    wire[31:0] PC_ctrl, imm_ctrl;
31	    30	
32	    31	
33	    32	    wire [31:0] PC_IF, next_PC_IF, PC_4_IF, inst_IF;
34	    33	
35	    34	    wire[31:0]inst_IS, PC_IS, Imm_out_IS;
36	    35	
37	    36	    wire[31:0]rs1_data_RO, rs2_data_RO, ALUA_RO, ALUB_RO;
38	    37	
39	    38	    wire FU_ALU_finish, FU_mem_finish, FU_mul_finish, FU_div_finish, FU_jump_finish, is_jump_FU;
40	    39	    wire[31:0]ALUout_FU, mem_data_FU, mulres_FU, divres_FU, PC_jump_FU, PC_wb_FU;
41	    40	
42	    41	    wire[31:0]ALUout_WB, mem_data_WB, mulres_WB, divres_WB, PC_wb_WB, wt_data_WB;
43	    42	
44	    43	
45	    44	    // IF
46	    45	    assign PC_EN_IF = IS_EN | FU_jump_finish & is_jump_FU;
47	    46	
48	    47	    REG32 REG_PC(.clk(debug_clk),.rst(rst),.CE(PC_EN_IF),.D(next_PC_IF),.Q(PC_IF));
49	    48	    
50	    49	    add_32 add_IF(.a(PC_IF),.b(32'd4),.c(PC_4_IF));
51	    50	
52	    51	    MUX2T1_32 mux_IF(.I0(PC_4_IF),.I1(PC_jump_FU),.s(FU_jump_finish & is_jump_FU),.o(next_PC_IF));
53	    52	
54	    53	    ROM_D inst_rom(.a(PC_IF[8:2]),.spo(inst_IF));
55	    54	
56	    55	
57	    56	    //Issue
58	    57	    REG_IF_IS reg_IF_IS(.clk(debug_clk),.rst(rst),.EN(IS_EN),
59	    58	        .flush(1'b0),.PCOUT(PC_IF),.IR(inst_IF),
60	    59	
61	    60	        .IR_IS(inst_IS),.PCurrent_IS(PC_IS));
62	    61	    
63	    62	    ImmGen imm_gen(.ImmSel(ImmSel_ctrl),.inst_field(inst_IS),.Imm_out(Imm_out_IS));
64	    63	
65	    64	    CtrlUnit ctrl(.clk(debug_clk),.rst(rst),.PC(PC_IS),.inst(inst_IS),.imm(Imm_out_IS),
66	    65	        .ALU_done(FU_ALU_finish),.MEM_done(FU_mem_finish),.MUL_done(FU_mul_finish),.DIV_done(FU_div_finish),.JUMP_done(FU_jump_finish),.is_jump(is_jump_FU),
67	    66	        .IS_en(IS_EN),.ImmSel(ImmSel_ctrl),.ALU_en(FU_ALU_EN),
68	    67	        .MEM_en(FU_mem_EN),.MUL_en(FU_mul_EN),.DIV_en(FU_div_EN),.JUMP_en(FU_jump_EN),
69	    68	        .PC_ctrl(PC_ctrl),.imm_ctrl(imm_ctrl),.rs1_ctrl(rs1_addr_ctrl),.rs2_ctrl(rs2_addr_ctrl),
70	    69	        .JUMP_op(Jump_ctrl),.ALU_op(ALUControl_ctrl),.ALU_use_PC(ALUSrcA_ctrl),.ALU_use_imm(ALUSrcB_ctrl),
71	    70	        .MEM_we(mem_w_ctrl),.MEM_bhw(bhw_ctrl),.MUL_op(),.DIV_op(),
72	    71	        .write_sel(DatatoReg_ctrl),.reg_write(RegWrite_ctrl),.rd_ctrl(rd_ctrl)    
73	    72	    );
74	    73	
75	    74	
76	    75	    // RO
77	    76	    Regs register(.clk(debug_clk),.rst(rst),
78	    77	        .R_addr_A(rs1_addr_ctrl),.rdata_A(rs1_data_RO),
79	    78	        .R_addr_B(rs2_addr_ctrl),.rdata_B(rs2_data_RO),
80	    79	        .L_S(RegWrite_ctrl),.Wt_addr(rd_ctrl),.Wt_data(wt_data_WB),
81	    80	        .Debug_addr(debug_addr[4:0]),.Debug_regs(debug_regs));
82	    81	
83	    82	    MUX2T1_32 mux_imm_ALU_RO_A(.I0(rs1_data_RO),.I1(PC_ctrl),.s(ALUSrcA_ctrl),.o(ALUA_RO));
84	    83	
85	    84	    MUX2T1_32 mux_imm_ALU_RO_B(.I0(rs2_data_RO),.I1(imm_ctrl),.s(ALUSrcB_ctrl),.o(ALUB_RO));
86	    85	
87	    86	
88	    87	    // FU
89	    88	    FU_ALU alu(.clk(debug_clk),.EN(FU_ALU_EN),.finish(FU_ALU_finish),
90	    89	        .ALUControl(ALUControl_ctrl),.ALUA(ALUA_RO),.ALUB(ALUB_RO),.res(ALUout_FU),
91	    90	        .zero(),.overflow());
92	    91	
93	    92	    FU_mem mem(.clk(debug_clk),.EN(FU_mem_EN),.finish(FU_mem_finish),
94	    93	        .mem_w(mem_w_ctrl),.bhw(bhw_ctrl),.rs1_data(rs1_data_RO),.rs2_data(rs2_data_RO),
95	    94	        .imm(imm_ctrl),.mem_data(mem_data_FU));
96	    95	
97	    96	    FU_mul mu(.clk(debug_clk),.EN(FU_mul_EN),.finish(FU_mul_finish),
98	    97	        .A(rs1_data_RO),.B(rs2_data_RO),.res(mulres_FU));
99	    98	
100	    99	    FU_div du(.clk(debug_clk),.EN(FU_div_EN),.finish(FU_div_finish),
101	   100	        .A(rs1_data_RO),.B(rs2_data_RO),.res(divres_FU));
102	   101	
103	   102	    FU_jump ju(.clk(debug_clk),.EN(FU_jump_EN),.finish(FU_jump_finish),
104	   103	        .JALR(Jump_ctrl[4]),.cmp_ctrl(Jump_ctrl[3:0]),.rs1_data(rs1_data_RO),.rs2_data(rs2_data_RO),
105	   104	        .imm(imm_ctrl),.PC(PC_ctrl),.PC_jump(PC_jump_FU),.PC_wb(PC_wb_FU),.is_jump(is_jump_FU));
106	   105	
107	   106	
108	   107	    // WB
109	   108	    REG32 reg_WB_ALU(.clk(debug_clk),.rst(rst),.CE(FU_ALU_finish),.D(ALUout_FU),.Q(ALUout_WB));
110	   109	
111	   110	    REG32 reg_WB_mem(.clk(debug_clk),.rst(rst),.CE(FU_mem_finish),.D(mem_data_FU),.Q(mem_data_WB));
112	   111	
113	   112	    REG32 reg_WB_mul(.clk(debug_clk),.rst(rst),.CE(FU_mul_finish),.D(mulres_FU),.Q(mulres_WB));
114	   113	
115	   114	    REG32 reg_WB_div(.clk(debug_clk),.rst(rst),.CE(FU_div_finish),.D(divres_FU),.Q(divres_WB));
116	   115	    
117	   116	    REG32 reg_WB_jump(.clk(debug_clk),.rst(rst),.CE(FU_jump_finish),.D(PC_wb_FU),.Q(PC_wb_WB));
118	   117	
119	   118	    MUX8T1_32 mux_DtR(.s(DatatoReg_ctrl),.I0(ALUout_WB),.I1(mem_data_WB),.I2(mulres_WB),.I3(divres_WB),
120	   119	        .I4(PC_wb_WB),.I5(32'd0),.I6(32'd0),.I7(32'd0),.o(wt_data_WB));
121	   120	
122	   121	    assign wb_addr = rd_ctrl;
123	   122	    assign wb_data = wt_data_WB;
124	   123	
125	   124	    always @(posedge debug_clk) begin
126	   125	        if (rst) begin
127	   126	            clk_counter <= 0;
128	   127	        end else begin
129	   128	            clk_counter <= clk_counter + 32'd1;
130	   129	        end
131	   130	    end
132	   131	
133	   132	    always @* begin
134	   133	        case (debug_addr[4:0])
135	   134	            0:  Test_signal = PC_IF;
136	   135	            1:  Test_signal = inst_IF;
137	   136	            2:  Test_signal = PC_IS;  
138	   137	            3:  Test_signal = inst_IS;
139	   138	
140	   139	            4:  Test_signal = rs1_addr_ctrl;
141	   140	            5:  Test_signal = rs1_data_RO;
142	   141	            6:  Test_signal = rs2_addr_ctrl;
143	   142	            7:  Test_signal = rs2_data_RO;
144	   143	
145	   144	            8:  Test_signal = ImmSel_ctrl;
146	   145	            9:  Test_signal = imm_ctrl;
147	   146	            10: Test_signal = ALUout_FU;
148	   147	            11: Test_signal = PC_EN_IF;
149	   148	
150	   149	            12: Test_signal = {15'b0, FU_ALU_EN, 15'b0, FU_ALU_finish};
151	   150	            13: Test_signal = ALUControl_ctrl;
152	   151	            14: Test_signal = ALUA_RO;
153	   152	            15: Test_signal = ALUB_RO;
154	   153	
155	   154	            16: Test_signal = {15'b0, FU_mem_EN, 15'b0, FU_mem_finish};
156	   155	            17: Test_signal = mem_w_ctrl;
157	   156	            18: Test_signal = bhw_ctrl;
158	   157	            19: Test_signal = mem_data_FU;
159	   158	
160	   159	            20: Test_signal = {15'b0, FU_mul_EN, 15'b0, FU_mul_finish};
161	   160	            21: Test_signal = mulres_FU;
162	   161	            22: Test_signal = {15'b0, FU_div_EN, 15'b0, FU_div_finish};
163	   162	            23: Test_signal = divres_FU;
164	   163	
165	   164	            24: Test_signal = {15'b0, FU_jump_EN, 15'b0, FU_jump_finish};
166	   165	            25: Test_signal = Jump_ctrl;
167	   166	            26: Test_signal = PC_jump_FU;
168	   167	            27: Test_signal = PC_wb_FU;
169	   168	
170	   169	            28: Test_signal = RegWrite_ctrl;
171	   170	            29: Test_signal = rd_ctrl;
172	   171	            30: Test_signal = DatatoReg_ctrl;
173	   172	            31: Test_signal = wt_data_WB;
174	   173	            
175	   174	            default: Test_signal = 32'hAA55_AA55;
176	   175	        endcase
177	   176	    end
178	   177	
179	   178	endmodule=============== core/CtrlUnit.v
180	     1	`timescale 1ns / 1ps
181	     2	`include "CtrlDefine.vh"
182	     3	
183	     4	module CtrlUnit(
184	     5	    input clk,
185	     6	    input rst,
186	     7	
187	     8	    input[31:0] PC,
188	     9	    input[31:0] inst,
189	    10	    input[31:0] imm,
190	    11	    
191	    12	    input ALU_done,
192	    13	    input MEM_done,
193	    14	    input MUL_done,
194	    15	    input DIV_done,
195	    16	    input JUMP_done,
196	    17	    input is_jump,
197	    18	
198	    19	    // IF
199	    20	    output IS_en,
200	    21	
201	    22	    // IS
202	    23	    output[2:0] ImmSel,
203	    24	
204	    25	    // RO/FU
205	    26	    output reg ALU_en, MEM_en, MUL_en, DIV_en, JUMP_en,
206	    27	    output reg[31:0] PC_ctrl,
207	    28	    output reg[31:0] imm_ctrl,
208	    29	    output reg[4:0] rs1_ctrl, rs2_ctrl, 
209	    30	    
210	    31	    // FU
211	    32	    output reg[4:0] JUMP_op,
212	    33	    output reg[3:0] ALU_op,
213	    34	    output reg ALU_use_PC,
214	    35	    output reg ALU_use_imm,
215	    36	    output reg MEM_we,
216	    37	    output reg[2:0] MEM_bhw,
217	    38	    output reg[2:0] MUL_op,
218	    39	    output reg[1:0] DIV_op,
219	    40	    
220	    41	    // WB
221	    42	    output reg[2:0] write_sel,
222	    43	    output reg reg_write,
223	    44	    output reg[4:0] rd_ctrl
224	    45	);
225	    46	    // used in for loop
226	    47	    integer i;
227	    48	
228	    49	    // Function Unit Status
229	    50	    // fields of FUS are defined at CtrlDefine.vh
230	    51	    reg[31:0] FUS[1:5];
231	    52	    reg[31:0] IMM[1:5];
232	    53	
233	    54	    // Register Status
234	    55	    // records which FU will write corresponding reg at WB
235	    56	    reg[2:0] RRS[0:31];
236	    57	
237	    58	    // sometimes an instruction needs PC to execute
238	    59	    // pc record
239	    60	    reg[31:0] PCR[1:5];
240	    61	
241	    62	    wire RO_en;
242	    63	    wire normal_stall;
243	    64	    reg ctrl_stall = 0, IS_flush = 0;
244	    65	
245	    66	    // a jump (JAL/JALR/BXX) instr has issued,
246	    67	    // stop issuing until result is known
247	    68	    wire jump_stall;
248	    69	
249	    70	    // instruction field
250	    71	    wire[6:0] funct7 = inst[31:25];
251	    72	    wire[2:0] funct3 = inst[14:12];
252	    73	    wire[6:0] opcode = inst[6:0];
253	    74	    wire[4:0] rd = inst[11:7];
254	    75	    wire[4:0] rs1 = inst[19:15];
255	    76	    wire[4:0] rs2 = inst[24:20];
256	    77	
257	    78	    // type specification
258	    79	    wire Rop = opcode == 7'b0110011;
259	    80	    wire Iop = opcode == 7'b0010011;
260	    81	    wire Bop = opcode == 7'b1100011;
261	    82	    wire Lop = opcode == 7'b0000011;
262	    83	    wire Sop = opcode == 7'b0100011;
263	    84	
264	    85	    wire funct7_0  = funct7 == 7'h0;
265	    86	    wire funct7_1  = funct7 == 7'h1;
266	    87	    wire funct7_32 = funct7 == 7'h20;
267	    88	
268	    89	    wire funct3_0 = funct3 == 3'h0;
269	    90	    wire funct3_1 = funct3 == 3'h1;
270	    91	    wire funct3_2 = funct3 == 3'h2;
271	    92	    wire funct3_3 = funct3 == 3'h3;
272	    93	    wire funct3_4 = funct3 == 3'h4;
273	    94	    wire funct3_5 = funct3 == 3'h5;
274	    95	    wire funct3_6 = funct3 == 3'h6;
275	    96	    wire funct3_7 = funct3 == 3'h7;
276	    97	
277	    98	    wire ADD  = Rop & funct3_0 & funct7_0;
278	    99	    wire SUB  = Rop & funct3_0 & funct7_32;
279	   100	    wire SLL  = Rop & funct3_1 & funct7_0;
280	   101	    wire SLT  = Rop & funct3_2 & funct7_0;
281	   102	    wire SLTU = Rop & funct3_3 & funct7_0;
282	   103	    wire XOR  = Rop & funct3_4 & funct7_0;
283	   104	    wire SRL  = Rop & funct3_5 & funct7_0;
284	   105	    wire SRA  = Rop & funct3_5 & funct7_32;
285	   106	    wire OR   = Rop & funct3_6 & funct7_0;
286	   107	    wire AND  = Rop & funct3_7 & funct7_0;
287	   108	
288	   109	    wire MUL    = Rop & funct3_0 & funct7_1;
289	   110	    wire MULH   = Rop & funct3_1 & funct7_1;
290	   111	    wire MULHSU = Rop & funct3_2 & funct7_1;
291	   112	    wire MULHU  = Rop & funct3_3 & funct7_1;
292	   113	    wire DIV    = Rop & funct3_4 & funct7_1;
293	   114	    wire DIVU   = Rop & funct3_5 & funct7_1;
294	   115	    wire REM    = Rop & funct3_6 & funct7_1;
295	   116	    wire REMU    = Rop & funct3_7 & funct7_1;
296	   117	
297	   118	    wire ADDI  = Iop & funct3_0;	
298	   119	    wire SLTI  = Iop & funct3_2;
299	   120	    wire SLTIU = Iop & funct3_3;
300	   121	    wire XORI  = Iop & funct3_4;
301	   122	    wire ORI   = Iop & funct3_6;
302	   123	    wire ANDI  = Iop & funct3_7;
303	   124	    wire SLLI  = Iop & funct3_1 & funct7_0;
304	   125	    wire SRLI  = Iop & funct3_5 & funct7_0;
305	   126	    wire SRAI  = Iop & funct3_5 & funct7_32;
306	   127	
307	   128	    wire BEQ = Bop & funct3_0;
308	   129	    wire BNE = Bop & funct3_1;
309	   130	    wire BLT = Bop & funct3_4;
310	   131	    wire BGE = Bop & funct3_5;
311	   132	    wire BLTU = Bop & funct3_6;
312	   133	    wire BGEU = Bop & funct3_7;
313	   134	
314	   135	    wire LB =  Lop & funct3_0;
315	   136	    wire LH =  Lop & funct3_1;
316	   137	    wire LW =  Lop & funct3_2;
317	   138	    wire LBU = Lop & funct3_4;
318	   139	    wire LHU = Lop & funct3_5;
319	   140	
320	   141	    wire SB = Sop & funct3_0;
321	   142	    wire SH = Sop & funct3_1;
322	   143	    wire SW = Sop & funct3_2;
323	   144	
324	   145	    wire LUI   = opcode == 7'b0110111;
325	   146	    wire AUIPC = opcode == 7'b0010111;
326	   147	
327	   148	    wire JAL  =  opcode == 7'b1101111;
328	   149	    wire JALR = (opcode == 7'b1100111) && funct3_0;
329	   150	
330	   151	    wire R_valid = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU 
331	   152	        | MUL | MULH | MULHSU | MULHU | DIV | DIVU | REM | REMU;
332	   153	    wire I_valid = ANDI | ORI | ADDI | XORI | SLLI | SRLI | SRAI | SLTI | SLTIU;
333	   154	    wire B_valid = BEQ | BNE | BLT | BGE | BLTU | BGEU;
334	   155	    wire L_valid = LW | LH | LB | LHU | LBU;
335	   156	    wire S_valid = SW | SH | SB;
336	   157	
337	   158	    // function unit specification
338	   159	    wire use_ALU = AND | OR | ADD | XOR | SLL | SRL | SRA | SUB | SLT | SLTU
339	   160	        | I_valid | LUI | AUIPC;
340	   161	    wire use_MEM = L_valid | S_valid;
341	   162	    wire use_MUL = MUL | MULH | MULHSU | MULHU;
342	   163	    wire use_DIV = DIV | DIVU | REM | REMU;
343	   164	    wire use_JUMP = B_valid | JAL | JALR;
344	   165	
345	   166	    wire[2:0] use_FU = {3{use_ALU}}  & `FU_ALU  |
346	   167	                       {3{use_MEM}}  & `FU_MEM  |
347	   168	                       {3{use_MUL}}  & `FU_MUL  |
348	   169	                       {3{use_DIV}}  & `FU_DIV  |
349	   170	                       {3{use_JUMP}} & `FU_JUMP ;
350	   171	
351	   172	    // registers to be used
352	   173	    wire[4:0] dst = {5{R_valid | I_valid | L_valid | LUI | AUIPC | JAL | JALR}} & rd;
353	   174	    wire[4:0] src1 = {5{R_valid | I_valid | S_valid | L_valid | B_valid | JALR}} & rs1;
354	   175	    wire[4:0] src2 = {5{R_valid | S_valid | B_valid}} & rs2;
355	   176	    // initial values of some FUS fields
356	   177	    wire[2:0] fu1 = RRS[src1];
357	   178	    wire[2:0] fu2 = RRS[src2];
358	   179	    wire rdy1 = ~|fu1;
359	   180	    wire rdy2 = ~|fu2;
360	   181	
361	   182	    // normal stall: structural hazard or WAW
362	   183	    assign normal_stall = ...;           //fill sth. here
363	   184	
364	   185	    assign IS_en = IS_flush | ~normal_stall & ~ctrl_stall;
365	   186	    assign RO_en = ~IS_flush & ~normal_stall & ~ctrl_stall;
366	   187	
367	   188	    always @ (posedge clk or posedge rst) begin
368	   189	        if (rst) begin
369	   190	            ctrl_stall <= 0;
370	   191	        end
371	   192	        else begin
372	   193	            // IS
373	   194	            if (RO_en & (use_FU == `FU_JUMP)) begin
374	   195	                ctrl_stall <= 1;
375	   196	            end
376	   197	            else if (JUMP_done) begin
377	   198	                ctrl_stall <= 0;
378	   199	            end
379	   200	        end
380	   201	    end
381	   202	
382	   203	    always @ (posedge clk or posedge rst) begin
383	   204	        if (rst) begin
384	   205	            IS_flush <= 0;
385	   206	        end
386	   207	        else if (JUMP_done & is_jump) begin
387	   208	            IS_flush <= 1;
388	   209	        end
389	   210	        else begin
390	   211	            IS_flush <= 0;
391	   212	        end
392	   213	    end
393	   214	
394	   215	    assign jump_stall = FUS[`FU_JUMP][`BUSY] & (~JUMP_done);
395	   216	
396	   217	    wire[4:0] op = {5{ADD}}          & `ALU_ADD    |
