`timescale 1ns / 1ps

module ALU(
    input[31:0] A, B,
    input[3:0] Control,
    output[31:0] res,
    output zero, overflow
);

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;

    // 实现：根据 Control 选择运算，并生成 zero / overflow 标志
    // The ALU must support: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
    // Use the Control input to select which operation to perform.
    // zero should be 1 when res is all zeros.
    // overflow should be set for signed ADD/SUB overflow.

    wire[31:0] res_ADD  = A + B;
    wire[31:0] res_SUB  = A - B;
    wire[31:0] res_AND  = A & B;
    wire[31:0] res_OR   = A | B;
    wire[31:0] res_XOR  = A ^ B;
    wire[31:0] res_SLL  = A << B[4:0];
    wire[31:0] res_SRL  = A >> B[4:0];
    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
    wire       res_lt   = $signed(A) < $signed(B);
    wire       res_ltu  = A < B;
    wire[31:0] res_SLT  = {31'b0, res_lt};
    wire[31:0] res_SLTU = {31'b0, res_ltu};
    wire[31:0] res_Ap4  = A + 32'd4;
    wire[31:0] res_Bout = B;

    wire is_ADD  = Control == ALU_ADD ;
    wire is_SUB  = Control == ALU_SUB ;
    wire is_AND  = Control == ALU_AND ;
    wire is_OR   = Control == ALU_OR  ;
    wire is_XOR  = Control == ALU_XOR ;
    wire is_SLL  = Control == ALU_SLL ;
    wire is_SRL  = Control == ALU_SRL ;
    wire is_SLT  = Control == ALU_SLT ;
    wire is_SLTU = Control == ALU_SLTU;
    wire is_SRA  = Control == ALU_SRA ;
    wire is_Ap4  = Control == ALU_Ap4 ;
    wire is_Bout = Control == ALU_Bout;

    assign res = {32{is_ADD }} & res_ADD  |
                 {32{is_SUB }} & res_SUB  |
                 {32{is_AND }} & res_AND  |
                 {32{is_OR  }} & res_OR   |
                 {32{is_XOR }} & res_XOR  |
                 {32{is_SLL }} & res_SLL  |
                 {32{is_SRL }} & res_SRL  |
                 {32{is_SLT }} & res_SLT  |
                 {32{is_SLTU}} & res_SLTU |
                 {32{is_SRA }} & res_SRA  |
                 {32{is_Ap4 }} & res_Ap4  |
                 {32{is_Bout}} & res_Bout ;

    assign zero = ~(|res);

    assign overflow = is_ADD  & (~(A[31] ^ B[31]) & (res_ADD[31] ^ A[31])) |
                      is_SUB  & ( (A[31] ^ B[31]) & (res_SUB[31] ^ A[31])) ;

endmodule===== lab3 RAM_B
`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    output [7:0] sim_uart_char_out,
    output sim_uart_char_valid,
    input[2:0] mem_u_b_h_w
);
    localparam SIZE = 256;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    // 地址译码：数据存储器只占用低地址空间，取地址低 ADDR_LINE 位
    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
    wire is_uart   = (addra == SIM_UART_ADDR);
    wire word_op   = mem_u_b_h_w[1];
    wire half_op   = mem_u_b_h_w[0];
    wire unsigned_op = mem_u_b_h_w[2];

    // 实现：按字节写入
    // Write byte/halfword/word based on mem_u_b_h_w control signals.
    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
    // Only write when wea is asserted. SIM_UART_ADDR writes should be excluded.
    always @(posedge clka) begin
        if (wea & ~is_uart) begin
            if (word_op) begin
                data[addr]                          <= dina[7:0];
                data[(addr + 1) % SIZE]             <= dina[15:8];
                data[(addr + 2) % SIZE]             <= dina[23:16];
                data[(addr + 3) % SIZE]             <= dina[31:24];
            end
            else if (half_op) begin
                data[addr]                          <= dina[7:0];
                data[(addr + 1) % SIZE]             <= dina[15:8];
            end
            else begin
                data[addr]                          <= dina[7:0];
            end
        end
    end

    // 实现：按字节读出并做符号/零扩展
    // Read byte/halfword/word based on mem_u_b_h_w.
    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
    // Return 0 if address is SIM_UART_ADDR.
    wire[31:0] rdata_w = {data[(addr + 3) % SIZE], data[(addr + 2) % SIZE],
                          data[(addr + 1) % SIZE], data[addr]};
    wire[15:0] rdata_h = {data[(addr + 1) % SIZE], data[addr]};
    wire[7:0]  rdata_b = data[addr];

    assign douta = is_uart ? 32'b0 :
                   word_op ? rdata_w :
                   half_op ? (unsigned_op ? {16'b0, rdata_h} : {{16{rdata_h[15]}}, rdata_h}) :
                             (unsigned_op ? {24'b0, rdata_b} : {{24{rdata_b[7]}},  rdata_b}) ;

    // 实现：串口模拟输出
    // Detect writes to SIM_UART_ADDR, latch character data, and output via sim_uart_char_out.
    reg[7:0] uart_char_reg;
    reg      uart_valid_reg;

    initial begin
        uart_char_reg  = 8'b0;
        uart_valid_reg = 1'b0;
    end

    always @(posedge clka) begin
        if (wea & is_uart) begin
            uart_char_reg  <= dina[7:0];
            uart_valid_reg <= 1'b1;
            // 仿真时直接把字符打印到控制台
            // synthesis translate_off
            $write("%c", dina[7:0]);
            // synthesis translate_on
        end
        else begin
            uart_valid_reg <= 1'b0;
        end
    end

    assign sim_uart_char_valid = uart_valid_reg;
    assign sim_uart_char_out   = uart_char_reg;
endmodule

